insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('pcv','bpy','PCV valve replacement','Engine',null,array['pcv','breather','oil separator','whistle','vacuum leak','p1297']::text[],true,'30 min',1) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('plugs','bpy','Spark plugs & coil packs','Engine',null,array['spark plug','coils','coil pack','ignition','misfire','red coils']::text[],true,'45 min',1.5) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into tasks (id,powertrain_id,title,category,group_name,aliases,live,time_label,difficulty) values ('catch-can','bpy','Oil catch can install','Engine',null,array['catch can','oil catch can','carbon buildup','breather','billet valve cover']::text[],true,'1.5–2 hr',2) on conflict (id) do update set title=excluded.title, category=excluded.category, group_name=excluded.group_name, aliases=excluded.aliases, live=excluded.live, time_label=excluded.time_label, difficulty=excluded.difficulty;
insert into guides (id,content) values ('pcv',$j${"id": "pcv", "title": "PCV valve replacement", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "pcv-hero", "alsoFits": "All 2.0T FSI (EA113): Mk5 GTI/Jetta, B6 Passat, Eos, A3 8P, TT 8J", "category": "Engine", "kind": "repair", "variants": {"question": "What's going on?", "hint": "The factory valve is a plastic diaphragm unit on the valve cover that fails often. You can fit the latest factory revision, or replace it with a machined plate as part of a catch-can setup.", "options": [{"id": "oe", "label": "Latest factory valve", "when": "Stock car, or you just want it fixed. Cheap and 20 minutes."}, {"id": "plate", "label": "Aftermarket plate (with a catch can)", "when": "Tuned car, or you're tired of replacing it. See the catch can guide for the rest."}]}, "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$50–120 (valve) · $80–250 (plate)", "risk": "Brittle plastic pipe clips", "why": "The PCV valve manages crankcase pressure and pulls oil vapour into the intake. On the FSI it's a plastic box with a rubber diaphragm that tears, and when it does the engine gets a giant vacuum leak: whistling idle, rough running, boost leaking past it, codes. It's the single most common FSI fault and one of the easiest fixes.", "note": "Two vendor procedures and a forum agree: four screws and two pipes. The hard part is buying the right revision."}, "heroCap": "Valve sits on top of the valve cover at the back. Two breather pipes plug into it; four T25 screws hold it down.", "lifespan": {"title": "When to expect it", "headline": ["Factory valves commonly fail between 40,000 and 80,000 miles, and the replacements fail too"], "earliest": "Some cars have eaten three or four", "detail": "The diaphragm tears from heat cycling and oil. The latest revisions (P and R) last longer but are still plastic and rubber. Symptoms range from a loud whistle at idle to nothing you'd notice except a vacuum leak code and a rough cold idle. A strong suck at the open oil cap with the engine idling is the classic confirmation.", "factors": ["Tuned car (more boost pressure on the check valve)", "Heat: hot climates, hard use", "Age of the rubber"], "inspect": ["Any rough idle or whistle: pull the oil cap at idle and feel for suction"], "confidence": {"level": "community", "n": 4, "note": "DAP articles and forum consensus. No factory interval; it's a failure item."}}, "should": {"yesIf": ["Whistle or whine from under the hood at idle", "Rough or hanging idle, especially cold", "Strong suction at the oil filler cap with the engine running", "Codes P1297, P0171, P0507, P2187", "Boost leak you can't find anywhere else"], "codes": ["P1297", "P0171", "P0507", "P2187"], "notes": ["Two different valves fit 2006 cars and they are not interchangeable: 06F 129 101 P (replaces E, G) and 06F 129 101 R (replaces N, L, K, F, C). The only reliable way to know yours is to read the number moulded into the bottom of the old valve. Buy by that, not by year.", {"text": "A plate on its own isn't a fix; it just moves the oil vapour somewhere else. Plates are meant to be part of a catch-can system that routes the vent through a separator and back to the turbo inlet. If you're going this way, this guide gets the old valve out and the catch can guide takes over.", "only": ["plate"]}], "confidence": {"level": "high", "n": 4, "note": "Symptoms and procedure agree across DAP, ECS and forum threads."}}, "parts": [{"tier": "oe", "name": "PCV valve, latest revision (P or R by your old part number)", "pn": "06F 129 101 P / 06F 129 101 R", "note": "OE-supplier (Febi, Hella) versions are the same unit", "price": "$50–120", "links": [], "only": ["oe"]}, {"tier": "oe", "name": "PCV valve gasket", "pn": "often not included", "note": "Check the box", "price": "$5", "links": [], "only": ["oe"]}, {"tier": "aftermarket", "name": "PCV plate / breather adapter", "pn": "see options below", "note": "Machined aluminium; pairs with a catch can", "price": "$80–250", "links": [], "only": ["plate"]}], "aftermarket": [{"name": "BSH / CTS PCV breather adapter", "note": "Replaces the valve with a billet plate and -AN port. Routes the vent to a catch can. Deletes the failure-prone diaphragm for good.", "price": "$80–150", "signal": "Pairs with a catch can", "links": []}, {"name": "Forge PCV bypass plate", "note": "UK favourite; same idea with push-fit for the factory pipe.", "price": "$100–150", "signal": "Alternative", "links": []}, {"name": "IE billet valve cover", "note": "Replaces the whole valve cover with ports for a catch can, removing the plastic breather plate too. The full solution; see the catch can guide.", "price": "$500+", "signal": "Full solution", "links": []}], "tools": [{"name": "T25 Torx"}, {"name": "Small flat screwdriver for the pipe clips; flashlight"}, {"name": "Torque wrench reading 3–4 Nm (¼\" inch-pound), or a light hand"}], "before": ["Engine cool.", "Look at the pipe clips first: they're brittle plastic. Work them gently, and buy a new pipe if one has already cracked.", "Have the old valve's part number in hand before you order the new one."], "steps": [{"n": 1, "title": "Engine cover off", "blocks": [{"t": "text", "b": "Unplug the MAF, pop the two inlet-pipe clips, lift the cover off its four grommets (see the air filter guide). The valve is the black box at the back of the valve cover, driver's side."}]}, {"n": 2, "title": "Upper breather pipe off", "blocks": [{"t": "text", "b": "The corrugated pipe from the valve to the intake manifold: squeeze the two retainer tabs at each end together and pull. Same at the manifold end."}, {"t": "ill", "id": "pcv-hero", "cap": "Upper pipe to the manifold, lower pipe from the block/valve cover, four screws. That's the whole job."}]}, {"n": 3, "title": "Lower breather pipe off", "blocks": [{"t": "text", "b": "The connector on the far side of the valve locks at four points (top, bottom, both sides). Pull back gently on the pipe and release each point in turn with a small screwdriver; keep the pull on so they don't re-lock. It slides off once all four are free."}, {"t": "warn", "b": "This connector breaks if you rush it. If it's already cracked, order the pipe with the valve."}]}, {"n": 4, "title": "Four screws, valve out", "blocks": [{"t": "text", "b": "Four T25 screws. Lift the valve straight up. Turn it over and read the part number moulded into the bottom; that's the family you need (P or R). Compare the new one's pipe angle to the old before you go further."}]}, {"n": 5, "title": "New valve in", "only": ["oe"], "blocks": [{"t": "text", "b": "New gasket if the old one is flattened or the box included one. Set the valve in place, four screws snug."}, {"t": "torque", "label": "PCV valve screws (T25 ×4)", "nm": 3.4, "c": {"level": "single", "n": 1, "note": "3.4 Nm (30 in-lb) from the ECS procedure for the same screws into the same plate. Plastic into aluminium: snug, no more."}}]}, {"n": 5, "title": "Plate in", "only": ["plate"], "blocks": [{"t": "text", "b": "Clean the valve cover face. New gasket or o-ring per the plate maker, plate on, factory screws snug (about 3.4 Nm). The lower breather pipe usually reconnects to the plate; the upper pipe's manifold port gets capped or routed per your catch-can kit. Continue in the catch can guide."}]}, {"n": 6, "title": "Pipes, cover, start", "blocks": [{"t": "text", "b": "Click both pipes back on (you'll feel each retainer lock). Cover on, MAF plugged in. Start it: the whistle should be gone and the idle steady within a minute. Pull the oil cap at idle; a gentle suction is normal, a hard pull is not."}]}], "alsoReplace": [{"name": "Breather pipes", "why": "Both are brittle plastic with clip ends. If either is cracked or the clips are tired, they're a boost leak waiting to happen."}, {"name": "Oil filler cap seal", "why": "Same crankcase; a hard, cracked cap seal is another leak."}, {"name": "Catch can", "why": "Same afternoon, same pipes. The guide for it is next in the list."}], "check": {"tab": "Is it the PCV?", "title": "Is the PCV really the problem?", "illId": "pcv-hero", "illCap": "The oil-cap test settles most of it.", "rows": [{"see": "Whistle at idle, strong suck at the oil cap", "means": "Torn diaphragm. Classic.", "do": "Replace the valve."}, {"see": "Rough idle, lean codes, no whistle", "means": "Could be PCV, could be the diverter valve or an intake leak.", "do": "Oil-cap test first; if it's mild, try the valve anyway, it's cheap. Then diverter valve."}, {"see": "Oil in the intercooler pipes and intake", "means": "PCV passing oil, or just an FSI being an FSI.", "do": "Valve, then a catch can."}], "c": {"level": "community", "n": 3, "note": "Vendor articles and forum diagnosis."}}, "aftercare": ["Note the revision you fitted for next time.", "If the idle stays rough after a day, look at the diverter valve next."], "disagreements": [{"topic": "P or R?", "pos": "Vendor listings by year contradict each other because both were fitted in 2006.", "call": "Read the old valve. Not the year."}, {"topic": "Fix or delete?", "pos": "Forums split between 'buy the latest revision' and 'delete it'.", "call": "Latest valve for a stock car; plate plus catch can for a tuned one or a repeat offender."}], "sources": ["DAP: FSI PCV failure article and revision guide", "VWVortex FSI PCV replacement thread", "ECS FSI catch can PDF (valve removal steps and torque)", "Europa Parts / Strictly European listings (VIN splits)", "Forge, CTS, BSH plate sheets"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('catch-can',$j${"id": "catch-can", "title": "Oil catch can install", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "catchcan-hero", "alsoFits": "2.0T FSI (EA113) only: Mk5 GTI/Jetta, B6 Passat, Eos, A3 8P, Golf R Mk6 (kits are engine-specific)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which setup?", "hint": "Kits differ in where they tap the crankcase vent. ECS keeps the factory valve cover and adds an adapter plate under the PCV; IE and CTS replace the plastic breather plate; IE's billet valve cover replaces the cover itself.", "options": [{"id": "ecs", "label": "ECS kit (factory valve cover)", "when": "Adapter plate under the PCV, PCV cap at the manifold. Best documented."}, {"id": "ie", "label": "IE or CTS kit (factory valve cover)", "when": "Billet breather adapter replaces the plastic plate on the cover."}, {"id": "billet", "label": "IE billet valve cover + can", "when": "New cover with ports. Removes every plastic breather part. Biggest job."}]}, "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$250–450 (kit) · $700+ with billet cover", "risk": "Routing under fuel lines · winter freeze", "why": "Direct injection means fuel never washes the intake valves. Oil vapour from the crankcase vent bakes onto them instead, and the FSI is famous for it: carbon buildup, lost power, rough idle by 80k. A catch can separates that oil out before it reaches the intake. It doesn't undo existing carbon, but it slows the next layer.", "note": "Vendors say under an hour; owners say two, mostly routing lines neatly. Straightforward either way."}, "heroCap": "Vent leaves the crankcase, passes through the baffled can where oil drops out, and clean vapour returns to the turbo inlet. Recirculated, so no mist in the engine bay and nothing vented to atmosphere.", "lifespan": {"title": "When owners do this", "headline": ["Usually with a tune, or after the first intake-valve carbon cleaning"], "earliest": null, "detail": "Nothing wears out; owners add a can once they understand the carbon problem, often at the same time as a PCV valve replacement since the parts overlap. Tuned cars run more crankcase pressure and make more vapour, so they benefit most.", "factors": ["Stage 2+ tune", "Cold climate short trips (more water in the vent)", "PCV valve failed again"], "inspect": ["Check the can weekly at first, then learn your interval. Empty it at about 2 inches of waste."], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor positioning; carbon-buildup mechanism is well established for direct injection."}}, "should": {"yesIf": ["Tuned car", "You've had or want to avoid intake-valve carbon cleaning", "Oil in the intercooler pipes", "Replacing the PCV valve anyway"], "codes": [], "notes": ["Recirculating kits (every one listed here) route clean vapour back to the turbo inlet. Vent-to-atmosphere setups with a little filter on the can are messy, smell, and are an emissions violation. Stay recirculated.", "Winter matters. Crankcase vapour is mostly water in cold weather; it collects in the can and lines and can freeze. ECS says drain weekly near freezing and reconnect the factory hose below freezing. Take that seriously: a frozen vent line pressurises the crankcase and blows seals."], "confidence": {"level": "high", "n": 3, "note": "Procedure and reasoning consistent across ECS, IE and CTS material."}}, "parts": [{"tier": "aftermarket", "name": "Catch can kit", "pn": "see options below", "note": "Can, bracket, lines with AN fittings, adapter plate or breather adapter, PCV cap", "price": "$250–450", "links": []}, {"tier": "aftermarket", "name": "IE billet valve cover", "pn": "IEBAVC5", "note": "Plus the matching can kit; the EVAP crossover relocation kit may be needed", "price": "$500+", "links": [], "only": ["billet"]}, {"tier": "oe", "name": "Valve cover gasket", "pn": "06F 103 483 D", "note": "New cover, new gasket", "price": "$25", "links": [], "only": ["billet"]}, {"tier": "oe", "name": "Clean engine oil for the o-rings, zip ties", "pn": "—", "note": "", "price": "—", "links": []}], "aftermarket": [{"name": "ECS baffled catch can kit", "note": "Adapter plate under the factory PCV, -10AN braided lines, bracket on the engine-mount stud, dipstick, serviceable baffles. 37-page install PDF with the winter warning.", "price": "$300–350", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_15317_Volkswagen_MK5_Golf_FSI_Oil_Catch_Can_Kit_Installation_r4.pdf"}]}, {"name": "IE recirculating kit (factory cover)", "note": "Billet breather adapter replaces the plastic plate on the valve cover, two -10AN hoses, T-handle drain, bracket on the passenger side. Owners: under an hour.", "price": "$300–400", "signal": "Cleanest install", "links": [{"store": "IE", "url": "https://eurosporttuning.com/ie-mk5-mk6-golf-r-2-0t-fsi-recirculating-catch-can-kit-for-oem-valve-cover/"}]}, {"name": "IE billet valve cover + can kit", "note": "Replaces the whole cover, removing the plastic breather plate and PCV. Needs the EVAP crossover relocation on some cars. The permanent fix for a tuned FSI.", "price": "$800–1,000", "signal": "Full solution", "links": [{"store": "IE", "url": "https://performancebyie.com/products/ie-billet-valve-cover-catch-can-kit-vw-audi-20t-fsi"}]}, {"name": "CTS Turbo kit", "note": "Breather adapter in place of the plastic plate, bracket, braided lines. Popular with the K04 crowd; brief install sheet.", "price": "$250–350", "signal": "Tuner pick", "links": []}, {"name": "034Motorsport billet can", "note": "Made for their other platforms; FSI owners adapt it with a breather adapter. Good hardware, more DIY.", "price": "$300+", "signal": "Mix-and-match", "links": []}], "tools": [{"name": "T25 and T30 Torx, 10mm socket with extension"}, {"name": "AN fitting wrench or adjustable wrench (tape the jaws), hose-clamp pliers, connector release tool"}, {"name": "Torque wrench reading 3–10 Nm", "only": ["ecs"]}, {"name": "T30, 10mm; valve cover bolt torque wrench (8–10 Nm); shop towels for oil", "only": ["billet"]}], "before": ["Engine cool. Read your kit's sheet alongside this; hardware and routing differ by brand.", "Lubricate every o-ring with clean engine oil before threading an AN fitting, and never over-tighten them: they strip.", "Route lines away from the belt, the exhaust side, and anything that moves."], "steps": [{"n": 1, "title": "Intake and cover off", "blocks": [{"t": "text", "b": "Inlet hose screws (T25) and clamp, MAF unplugged, two inlet-pipe clips, engine cover off its grommets (driver front, driver rear, passenger rear, passenger front, as ECS orders it, to avoid cracking it)."}]}, {"n": 2, "title": "Upper breather pipe off, cap the manifold", "only": ["ecs"], "blocks": [{"t": "text", "b": "Squeeze the retainers and pull the corrugated pipe off the PCV valve and the intake manifold. Oil the o-rings on the kit's PCV cap and push it onto the manifold port (or onto a boost tap if you have one) until fully seated, then fit its retaining clip. The manifold side is now closed."}]}, {"n": 2, "title": "Breather plate off", "only": ["ie"], "blocks": [{"t": "text", "b": "The plastic breather plate sits on the valve cover with the breather hose on it. Disconnect the hose and any lines, then remove the plate's T25 screws. Coil-pack connectors may need to be unplugged for clearance; note their order."}]}, {"n": 2, "title": "Old valve cover off", "only": ["billet"], "blocks": [{"t": "text", "b": "Unplug all four coil packs and pull the coils (see the plugs guide), disconnect the PCV pipes and breather hose, the EVAP line and any brackets on the cover, then the cover bolts in a spiral from the outside in. Lift the cover; the gasket may stick. Clean the head's sealing face with a plastic scraper and a rag.", "only": ["billet"]}, {"t": "warn", "b": "Nothing falls into an open cylinder head. Rag over the cam area while you clean the face, and count your tools.", "only": ["billet"]}]}, {"n": 3, "title": "Lower pipe and PCV valve out", "only": ["ecs"], "blocks": [{"t": "text", "b": "Release the lower breather pipe's four-point connector (see the PCV guide), then the four T25 screws, and lift the valve out. Keep the screws; they hold the adapter plate."}]}, {"n": 4, "title": "Reroute the vacuum line and air tube", "only": ["ecs"], "blocks": [{"t": "text", "b": "To make room for the lines: remove the three T30 screws on the vacuum-line and air-tube hold-down clamps, unplug the HPFP pressure-sensor connector and unclip the vacuum line from the fuel line, disconnect the air tube from the valve cover, flip the clamps as the PDF shows, slide the near clamp along the line to meet the air-tube bracket, and refit the screws so both lines now run the new path. Reconnect the sensor and clip."}, {"t": "note", "b": "This is the only fiddly part of the ECS kit and the reason it takes two hours rather than one. The PDF's before/after photos are worth having open."}]}, {"n": 5, "title": "Adapter plate on, lines under the fuel lines", "only": ["ecs"], "blocks": [{"t": "text", "b": "Oil the 90° fitting on the feed line and thread it into the bottom of the adapter plate by hand, snug. Guide the feed line (plate attached) under the vacuum tube, under the engine-cover bracket and under the fuel lines. Fit the plate with the factory screws, reconnect the lower breather pipe to it. Route the return line the same way and thread it into the plate's side port."}, {"t": "torque", "label": "Adapter plate screws (T25 ×4)", "nm": 3.4, "c": {"level": "single", "n": 1, "note": "ECS: 3.4 Nm (30 in-lb). Snug; plastic and aluminium."}}]}, {"n": 5, "title": "Breather adapter on", "only": ["ie"], "blocks": [{"t": "text", "b": "Fit the kit's billet adapter where the plastic plate was, with its gasket or o-ring, using the factory or supplied screws, snug. Thread the two -10AN hose ends into it by hand with oiled o-rings. Reconnect the coil packs in order."}]}, {"n": 5, "title": "New cover on", "only": ["billet"], "blocks": [{"t": "text", "b": "New gasket into the billet cover's groove, cover onto the head, bolts snug in a spiral from the centre out, then torque per IE's sheet (factory spec is about 10 Nm). Reinstall coils and connectors. Fit the block breather adapter and thread the can's hoses into the cover ports. If the EVAP crossover fouls the new cover, IE's relocation kit moves it."}, {"t": "torque", "label": "Valve cover bolts", "nm": 10, "c": {"level": "single", "n": 1, "note": "Factory-style value; follow IE's sheet for their cover."}}]}, {"n": 6, "title": "Mount the can", "blocks": [{"t": "text", "b": "Bracket onto the stud on the end of the engine-mount bolt and the threaded hole in the body (clean it; don't strip the paint off the threads), bolt and nut to 10 Nm. Can into the bracket with the reservoir loose so it can rotate while you connect the hoses.", "only": ["ecs"]}, {"t": "text", "b": "Kit bracket to its mounting point (passenger side on IE, per the sheet on CTS); can into the bracket loose enough to rotate.", "only": ["ie", "billet"]}, {"t": "torque", "label": "Bracket bolt and nut", "nm": 10, "c": {"level": "single", "n": 1, "note": "ECS figure; other kits say snug."}, "only": ["ecs"]}]}, {"n": 7, "title": "Connect and route the lines", "caution": true, "blocks": [{"t": "text", "b": "Feed line to the can's feed side, return line to the return side (they're marked, and the baffles only work one way). Oil the o-rings, thread by hand, snug with a taped wrench. Then look at every inch of both lines: under the fuel lines, clear of brackets, no contact with anything that vibrates or gets hot. Adjust, then lock the can by tightening its reservoir."}, {"t": "ill", "id": "catchcan-hero", "cap": "Feed side has the holed baffle; return side is a flat plate. Backwards means the can does nothing."}, {"t": "warn", "b": "A line rubbing a bracket wears through in months, and a crankcase vent open to the bay is an oil mess plus a lean condition. Ten minutes of routing now."}]}, {"n": 8, "title": "Cover on, start, check", "blocks": [{"t": "text", "b": "Engine cover back on (check the hoses clear it), inlet pipe, MAF. Start it, listen for hiss at any fitting, check for a steady idle. Drive it a week, then pull the dipstick or open the drain and see what you caught."}]}], "alsoReplace": [{"name": "PCV valve", "why": "With the ECS kit the factory valve is removed anyway; with the others it stays. If it stays and it's original, replace it now."}, {"name": "Breather hoses and pipes", "why": "Brittle plastic clips; if any are cracked, new ones now."}, {"name": "Intake-valve carbon cleaning", "why": "The can slows new buildup; it doesn't remove old. On a 100k car with rough idle, a walnut-blast cleaning is the companion job."}], "check": {"tab": "Which path?", "title": "Which setup fits you?", "illId": "catchcan-hero", "illCap": "All three end up in the same place: vent through a can, back to the turbo inlet.", "rows": [{"see": "Stock-ish car, want the documented route", "means": "ECS keeps the factory cover and has a full PDF.", "do": "ECS kit. Replace the PCV valve while it's out."}, {"see": "Tuned, want the tidiest install under an hour", "means": "Breather adapter kits are the least intrusive.", "do": "IE or CTS kit."}, {"see": "Tuned, tired of plastic breather parts", "means": "The cover itself is the last plastic piece.", "do": "IE billet cover with their can kit."}], "c": {"level": "community", "n": 3, "note": "Vendor material and owner reports."}}, "aftercare": ["Check the can weekly for the first month, then set your own interval. Empty at about 2 inches.", "Clean the separator baffles twice a year (ECS).", "Below freezing: drain weekly, or reconnect the factory hose for the winter. Not a suggestion."], "disagreements": [{"topic": "Recirculate or vent?", "pos": "Some forum builds vent to a filter on the can.", "call": "Recirculate. Every vendor does; venting is messy and illegal."}, {"topic": "Keep the PCV valve?", "pos": "ECS caps the manifold path and keeps a valve-shaped plate; IE and CTS replace the breather plate instead.", "call": "Both work. Pick by which parts you want to stop buying."}, {"topic": "How long?", "pos": "'Under an hour' (IE owners) vs two (ECS routing).", "call": "1.5–2 hr first time."}], "sources": ["ECS Tuning Mk5 FSI baffled oil catch can installation PDF (r4)", "IE catch can product pages (factory cover and billet cover kits)", "CTS Turbo FSI catch can install sheet", "VWVortex 'How-To PCV Catch Can TSI, FSI and TFSI'", "034Motorsport catch can guides (technique)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('plugs',$j${"id": "plugs", "title": "Spark plugs & coil packs", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "ignition-hero", "alsoFits": "All 2.0T FSI and TSI (same plugs and coils)", "category": "Engine", "kind": "repair", "variants": {"question": "Stock or tuned?", "hint": "Tuned cars run more cylinder pressure and want a colder plug with a slightly smaller gap.", "options": [{"id": "stock", "label": "Stock or Stage 1", "when": "Factory-spec plug at 0.8 mm (.032\")"}, {"id": "tuned", "label": "Stage 2, K04 or bigger", "when": "One range colder, gapped to 0.7 mm (.028\")"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$40–60 plugs · $60–120 coils", "risk": "Cross-threading a plug · dropping debris in the plug well", "why": "Plugs wear and coils die, and on a turbo engine both show up as a misfire under boost before anything else. It's a twenty-minute job with the right socket, and coils on this engine just pull out: no bolts.", "note": "Every source agrees on the procedure. The arguments are about plug choice and gap, so those are laid out below."}, "heroCap": "Coil packs sit in the plug wells on top of the valve cover, one per cylinder, held by friction. Unplug, pull straight up, and the plug is below on a 5/8\" (16mm) socket.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Plugs: every 40,000 miles; coils when they fail", "only": ["stock"]}, {"text": "Plugs: every 20,000–30,000 miles on a tuned car; iridium lasts longer than copper", "only": ["tuned"]}], "earliest": "Copper race plugs (BKR7E) need changing every 12,000–15,000", "detail": "A tired plug misfires under load first: a stumble at full boost in third that goes away at part throttle. A dying coil is the same symptom on one cylinder, with a code that names it. Coils on the FSI were revised several times; the latest black revision and the red 'R8' coil are the same part in different colours.", "factors": ["Tune", "Oil in the plug wells from a leaking valve cover gasket (kills coils)", "Wrong gap for the boost level"], "inspect": ["Any misfire code: pull the coil on that cylinder and swap it with a neighbour. If the code follows the coil, it's the coil."], "confidence": {"level": "community", "n": 4, "note": "Owner practice and vendor kit notes; the factory table wasn't fetched this pass."}}, "should": {"yesIf": ["Misfire under boost, worse when it's cold and damp", "Misfire code on a specific cylinder (P0301–P0304)", "40k since the last plugs, or unknown", "Just tuned it and still on stock plugs"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304"], "notes": ["Plug choice, decoded: Bosch FR6KPP332S is the factory plug. NGK PFR7S8EG is the same family one heat range colder and is what most kits ship now. NGK BKR7EIX is an iridium plug one range colder than the Bosch, favoured for tuned cars. 'Colder' means the plug sheds heat faster; it does not add power on a stock car.", {"text": "Gap: pre-gapped 0.8 mm (.032\") is right for stock and Stage 1. Don't re-gap platinum tips with a tool; check with a wire gauge only.", "only": ["stock"]}, {"text": "Gap: close them to 0.7 mm (.028\"). Too wide and the spark blows out under boost, which is your full-throttle misfire; too narrow and cold starts and idle suffer. Tuners publish their number; APR's K04 guidance is .028 or a touch under.", "only": ["tuned"]}, "Coils: the red Audi R8 coil (06E905115E) and the current black VW coil (07K905715G / 06H905115B) are identical apart from colour and are the latest revision. Red doesn't make more spark; it just looks good and is a reliable part."], "confidence": {"level": "high", "n": 4, "note": "Plug families, gaps and coil equivalence agree across a parts specialist's listing and multiple forum threads."}}, "parts": [{"tier": "oe", "name": "Spark plugs (×4), NGK PFR7S8EG or Bosch FR6KPP332S", "pn": "06H 905 601 A", "note": "Pre-gapped .032\"", "price": "$40–60", "links": [], "only": ["stock"]}, {"tier": "aftermarket", "name": "Spark plugs (×4), NGK BKR7EIX iridium", "pn": "NGK 2667", "note": "One range colder; gap to .028\"", "price": "$40–50", "links": [], "only": ["tuned"]}, {"tier": "oe", "name": "Ignition coils (×4), latest revision", "pn": "07K905715G / 06H905115B (black) · 06E905115E (red)", "note": "Identical internals", "price": "$60–120", "links": []}, {"tier": "oe", "name": "Dielectric grease, anti-seize (tiny amount, optional)", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "Red 'R8' coils (06E905115E)", "note": "Same part as the latest black coil, different colour. Cheap, reliable, and the forums love the look. No performance change.", "price": "$60–90 / set", "signal": "Same part, red", "links": []}, {"name": "NGK BKR8EIX (two ranges colder)", "note": "For big-turbo builds. Too cold for a Stage 2 daily; it'll foul.", "price": "$40–50", "signal": "Big-turbo only", "links": []}, {"name": "NGK BKR7E copper", "note": "Race plug: cheap, great spark, 12–15k life. For cars that see the plug wrench often.", "price": "$12", "signal": "Track consumable", "links": []}], "tools": [{"name": "5/8\" (16mm) thin-wall spark plug socket with rubber insert, 3/8\" ratchet and extension"}, {"name": "Torque wrench to 30 Nm"}, {"name": "Wire-type gap gauge (not a coin-style disc)"}, {"name": "Coil puller or a strong grip; small flat screwdriver for the connector locks; compressed air or a vacuum for the wells"}], "before": ["Engine cold. Plug threads in a hot aluminium head strip easily.", "Blow or vacuum the wells out before the plugs come out so nothing drops into the cylinder.", "Do one cylinder at a time so nothing gets mixed up."], "steps": [{"n": 1, "title": "Cover off, unplug the coils", "blocks": [{"t": "text", "b": "Engine cover off (air filter guide). Four coils in a row on the valve cover. Press or lift each connector's lock tab with a small screwdriver and unplug it."}]}, {"n": 2, "title": "Pull the coils", "blocks": [{"t": "text", "b": "Grip the coil by its body and pull straight up; they're a friction fit and can be stubborn. A coil puller tool helps; a wide screwdriver under the coil's lip, gently, is the owner method. Look at each one: cracks in the boot or oil on it mean the coil is dead or the cover gasket is leaking."}, {"t": "ill", "id": "ignition-hero", "cap": "No bolts. Unplug, pull straight up, plug is directly below."}]}, {"n": 3, "title": "Plugs out", "blocks": [{"t": "text", "b": "Blow the wells clear. 5/8\" plug socket on an extension, break each plug loose and spin it out. Read them as they come out (see the table below); a plug that's oily or white tells you something."}]}, {"n": 4, "title": "Gap and fit the new plugs", "caution": true, "blocks": [{"t": "text", "b": "Check the gap with a wire gauge without touching the centre electrode: 0.8 mm (.032\") for stock. If it's off, adjust by bending the ground strap only, gently.", "only": ["stock"]}, {"t": "text", "b": "Check and set the gap to 0.7 mm (.028\") with a wire gauge, bending only the ground strap. Iridium centre electrodes chip if you lever on them.", "only": ["tuned"]}, {"t": "text", "b": "Thread each plug in by hand, using the socket without the ratchet, until it seats. If it resists before seating, back out and restart; never force it. Then torque."}, {"t": "torque", "label": "Spark plugs (flat seat with gasket)", "nm": 25, "alt": [30], "c": {"level": "varies", "n": 2, "note": "No factory figure was confirmed this pass; kit sheets and forums quote 25–30 Nm for this gasketed flat-seat plug. Either is fine. Hand-tight plus a firm quarter turn lands here."}}, {"t": "warn", "b": "Cross-threading a plug in an aluminium head is the one way this job goes badly. Hand start, every time."}]}, {"n": 5, "title": "Coils in, plugs in the connectors", "blocks": [{"t": "text", "b": "Dab of dielectric grease inside each coil boot. Push each coil down until it seats over the plug with a definite stop. Connectors on until they click. Cover on."}]}, {"n": 6, "title": "Start and drive", "blocks": [{"t": "text", "b": "Idle should be smooth immediately. Drive it and give it full throttle in a middle gear once warm; a stumble that's gone is the point. A stumble that remains with new plugs and coils is not ignition: think PCV, diverter valve, or fuel."}]}], "alsoReplace": [{"name": "Valve cover gasket", "why": "Oil in the plug wells kills coils. If the wells are wet, the gasket is the cause and it's a one-hour job."}, {"name": "PCV valve", "why": "Rough idle blamed on plugs is often the PCV. Same access."}], "check": {"tab": "Read the plugs", "title": "Reading the old plugs", "illId": "ignition-hero", "illCap": "Tan is right. Everything else is a clue.", "rows": [{"see": "Light tan to grey electrode, no deposits", "means": "Healthy engine, plug simply aged.", "do": "Replace, same type."}, {"see": "Black, sooty and dry", "means": "Rich, or the plug is too cold for the car, or lots of idling.", "do": "Check gap and heat range; if you fitted BKR8s on a Stage 1, that's why."}, {"see": "Oily, wet", "means": "Oil in the well from the cover gasket, or oil past the rings/PCV.", "do": "Gasket first; new coil on that cylinder."}, {"see": "White, blistered, tiny beads on the electrode", "means": "Too hot: lean, too much boost, or the plug is too hot a range.", "do": "Colder plug and a look at the tune before you damage a piston."}], "c": {"level": "community", "n": 3, "note": "Standard plug reading; consistent with forum experience on this engine."}}, "aftercare": ["Note mileage and plug type in the glovebox.", "Misfire returns on one cylinder: swap coils between cylinders and see if it moves."], "disagreements": [{"topic": "Gap", "pos": ".032 vs .028 vs .024.", "call": ".032 stock, .028 tuned; .024 is APR's K04 kit number."}, {"topic": "Do red coils help?", "pos": "Forum lore says more spark.", "call": "Identical to the latest black coil. Buy them for the colour."}, {"topic": "Plug torque", "pos": "25 vs 30 Nm; factory value not confirmed.", "call": "25–30, flagged."}], "sources": ["VWVortex 'Correct Spark Plug Gap 2.0T FSI'", "Audizine red-coil and plug swap threads", "Europa Parts ignition kit listing (coil equivalence, plug families)", "UroTuning tune-up kit listing", "Black Forest Industries BKR7E note"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
